// Tag each contact with which email to send
const results = [];
const source = $input.context.node.name;

for (const item of $input.all()) {
  let emailType = 'initial';
  if (source.includes('Follow-up 1')) emailType = 'followup1';
  else if (source.includes('Follow-up 2')) emailType = 'followup2';
  else if (source.includes('Follow-up 3')) emailType = 'followup3';

  results.push({ json: { ...item.json, emailType } });
}

return results;

