// Build subject and body based on emailType
const results = [];

for (const item of $input.all()) {
  const c = item.json;
  const name = c.first_name || 'there';
  const company = c.company || 'your company';
  let subject = '';
  let body = '';

  if (c.emailType === 'initial') {
    subject = `Partnership Opportunity – ${company}`;
    body = `Hi ${name},

I hope this message finds you well. My name is [YOUR NAME] and I represent [YOUR COMPANY].

I came across ${company} and believe there's a great opportunity to collaborate on [VALUE PROPOSITION].

Would you be open to a quick 15-minute call this week to explore how we might work together?

Looking forward to connecting.

Best regards,
[YOUR NAME]
[YOUR TITLE]
[YOUR PHONE]`;
  } else if (c.emailType === 'followup1') {
    subject = `Following up – ${company}`;
    body = `Hi ${name},

I wanted to follow up on my previous email. I understand you're busy, so I'll keep this brief.

I genuinely think there's value in a quick conversation about [VALUE PROPOSITION].

Do you have 15 minutes this week?

Best,
[YOUR NAME]`;
  } else if (c.emailType === 'followup2') {
    subject = `Last check-in – ${company}`;
    body = `Hi ${name},

I've reached out a couple of times and haven't heard back — I completely understand if now isn't the right time.

If you're interested in exploring how [YOUR COMPANY] can help ${company}, I'd love to connect. If not, no worries at all.

Either way, wish you and the team at ${company} all the best!

Best,
[YOUR NAME]`;
  } else if (c.emailType === 'followup3') {
    subject = `Closing the loop – ${company}`;
    body = `Hi ${name},

This will be my last follow-up. If there's ever a time that [VALUE PROPOSITION] becomes relevant, please don't hesitate to reach out.

Wishing you continued success!

Warm regards,
[YOUR NAME]`;
  }

  results.push({ json: { ...c, emailSubject: subject, emailBody: body } });
}

return results;
